ops.ops_ingestion_log (\n","  log_id STRING, batch_id STRING, job_name STRING, signal STRING, stage STRING,\n","  source_file STRING, window_start_utc STRING, window_end_utc STRING,\n","  rows_bronze BIGINT, rows_silver BIGINT, rows_dlq BIGINT, rows_duplicates_removed BIGINT,\n","  status STRING, error_message STRING, started_at TIMESTAMP, finished_at TIMESTAMP\n",") USING DELTA\"\"\")\n","\n","if spark.table(\"ops.ops_watermark\").count() == 0:\n","    (spark.createDataFrame([(s, \"1900-01-01T00:00:00Z\") for s in SIGNALS],\n","                           \"signal string, watermark_utc string\")\n","          .withColumn(\"updated_at\", F.current_timestamp())\n","          .write.mode(\"append\").saveAsTable(\"ops.ops_watermark\"))"],"outputs":[{"output_type":"display_data","data":{"application/vnd.livy.statement-meta+json":{"spark_pool":null,"statement_id":4,"statement_ids":[4],"state":"finished","livy_statement_state":"available","spark_jobs_updating":false,"session_id":"888121a3-0cbc-40dd-beee-53a4ed4e682d","normalized_state":"finished","queued_time":"2026-10-26T05:41:39.6839654Z","session_start_time":null,"execution_start_time":"2026-10-26T05:41:39.6851068Z","execution_finish_time":"2026-10-26T05:42:00.207374Z","parent_msg_id":"d9a134a6-2d95-4848-82d4-61ec8ff112d2"},"text/plain":"StatementMeta(, 888121a3-0cbc-40dd-beee-53a4ed4e682d, 4, Finished, Available, Finished, False)"},"metadata":{}}],"execution_count":2,"metadata":{"microsoft":{"language":"python","language_group":"synapse_pyspark"}},"id":"76e513b3-e016-405d-9041-39dad1702edf"},{"cell_type":"code","source":["for f in mssparkutils.fs.ls(\"Files/reference\"):\n","    if not f.name.endswith(\".csv\") or f.name.startswith(\"vehicles_\"):\n","        continue\n","    df = spark.read.option(\"header\", True).option(\"inferSchema\", True).csv(f.path)\n","    df.write.mode(\"overwrite\").option(\"overwriteSchema\", \"true\").saveAsTable(f\"ref.ref_{f.name[:-4]}\")\n","\n","vdf = (spark.read.option(\"header\", Tru